code.cpp:
class Solution {
public:
    int numberOfSpecialChars(string word) {
        int firstUpper[26];
        int lastLower[26];
        for (int i = 0; i < 26; i++) {
            firstUpper[i] = -1;
            lastLower[i] = -1;
        }
        for (int i = 0; i < (int)word.size(); i++) {
            char c = word[i];
            if (c >= 'a' && c <= 'z') {
                lastLower[c - 'a'] = i;
            } else {
                int idx = c - 'A';
                if (firstUpper[idx] == -1) {
                    firstUpper[idx] = i;
                }
            }
        }
        int count = 0;
        for (int i = 0; i < 26; i++) {
            if (firstUpper[i] != -1 && lastLower[i] != -1 && lastLower[i] < firstUpper[i]) {
                count++;
            }
        }
        return count;
    }
};
